@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;0,700;0,800;1,600;1,700&display=swap');
:root{--ink:#17232a;--muted:#758086;--cream:#f5f2e9;--paper:#fbfaf6;--red:#bd4d43;--pine:#315a4e;--line:#e6e3d9;--gold:#d8aa61;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',Georgia,serif}
*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(#d7d4ca 0.6px,transparent .6px);background-size:18px 18px}.page-shell{max-width:1390px;padding:0 6.1%;margin:auto}.topbar{height:74px;border-bottom:1px solid #dcd9d0;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font-size:13px;font-weight:800;letter-spacing:.11em;color:var(--ink);text-decoration:none}.brand-mark{font-size:21px;color:var(--red)}.brand-light{font-weight:500;color:#78817e}.chapter-label,.sound-toggle,.eyebrow,.panel-heading,.location,.alert-status,.meter-label,.meter-state,.overlay-hint,.side-footer,.page-footer,.step-count,.code-clue>span{font-family:var(--mono);letter-spacing:.1em}.chapter-label{font-size:10px;color:#7a8584;display:flex;gap:9px;align-items:center}.live-dot{width:7px;height:7px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px #bd4d431a}.sound-toggle{border:0;background:transparent;color:#4b5e5a;cursor:pointer;font-size:12px;padding:10px}.sound-toggle span{font-size:10px;letter-spacing:.04em;margin-left:4px}.intro-row{display:flex;align-items:flex-end;justify-content:space-between;padding:36px 0 27px;gap:24px}.eyebrow{margin:0 0 12px;color:var(--red);font-size:9px;font-weight:500;letter-spacing:.16em}.intro-row h1{font-family:var(--serif);font-size:clamp(35px,4.2vw,55px);line-height:1.04;letter-spacing:-.04em;margin:0;font-weight:700}.intro-row h1 em{color:var(--pine);font-weight:600}.mobile-break{display:none}.subtitle{color:#697477;font-size:13px;margin:12px 0 0;letter-spacing:.01em}.story-chip{display:flex;gap:12px;align-items:flex-start;border-left:1px solid #d9d4c8;padding:5px 0 5px 16px;color:#74807d;font-size:11px;line-height:1.7;min-width:220px}.story-chip b{font:10px var(--mono);letter-spacing:.12em;color:#3f514d}.chip-icon{color:var(--red);font-size:21px;margin-top:3px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:22px;align-items:stretch}.game-frame{background:#121d22;border:1px solid #263137;box-shadow:0 16px 38px #1a2a3023;min-width:0}.game-topline{height:40px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #253238;color:#c3d0c8}.location{font-size:9px;display:flex;gap:9px;align-items:center;letter-spacing:.14em}.location-icon{font-size:16px;color:#d4ad71}.alert-status{font-size:9px;letter-spacing:.13em;color:#a6b0a7;display:flex;gap:7px;align-items:center}.status-dot{width:6px;height:6px;border-radius:50%;background:#79a78c}.alert-status.alerted{color:#e39774}.alert-status.alerted .status-dot{background:#e27557;box-shadow:0 0 0 4px #e2755726}.canvas-wrap{position:relative;width:100%;overflow:hidden;background:#1a292a}.canvas-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:22/16;image-rendering:pixelated}.game-footline{height:42px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #253238;gap:15px}.stealth-meter{display:flex;gap:9px;align-items:center}.meter-label,.meter-state{font-size:8px;letter-spacing:.12em;color:#84918d}.meter-track{width:104px;height:5px;border-radius:4px;background:#35433e;overflow:hidden}.meter-fill{height:100%;width:0;background:#d9694e;transition:width .14s linear,background .2s}.meter-state{color:#85ae91}.meter-state.danger{color:#e28368}.foot-note{font-size:10px;color:#9eaaa5}.foot-dot{display:inline-block;width:5px;height:5px;background:#d4ad71;border-radius:50%;margin-right:5px}.side-panel{background:var(--paper);border:1px solid #e8e4da;box-shadow:0 9px 24px #2837310c;display:flex;flex-direction:column}.panel-block{padding:18px 19px 16px;border-bottom:1px solid var(--line)}.panel-heading{font-size:9px;letter-spacing:.14em;display:flex;align-items:center;justify-content:space-between;color:#43504c;font-weight:500}.step-count{font-size:9px;color:#8b9189}.panel-description,.threat-block>p{font-size:11px;line-height:1.6;color:#78817d;margin:9px 0 14px}.objectives{list-style:none;padding:0;margin:0}.objectives li{display:flex;align-items:center;gap:10px;padding:8px 0;border-top:1px solid #efede6;transition:opacity .2s}.check-box{width:15px;height:15px;border:1px solid #d6d3c9;border-radius:3px;flex-shrink:0;display:grid;place-items:center;color:#fff;font-size:10px}.check-box span{opacity:0}.objective-copy{display:flex;flex-direction:column;gap:3px;flex:1}.objective-copy b{font-size:11px;font-weight:600;color:#343f3b}.objective-copy small{font-size:9px;color:#9a9d94}.objective-icon{font-size:17px;color:#98a199}.objectives li.done .check-box{border-color:var(--pine);background:var(--pine)}.objectives li.done .check-box span{opacity:1}.objectives li.done .objective-copy b{color:var(--pine)}.objectives li.done .objective-copy small{color:#84968b}.objectives li.done .objective-icon{color:#b4c5b7}.code-clue{margin-top:11px;background:#edf2eb;border-left:2px solid var(--pine);padding:9px 11px;display:flex;justify-content:space-between;align-items:center}.code-clue[hidden]{display:none}.code-clue>span{font-size:8px;color:#748078}.code-clue>b{font:500 14px var(--mono);letter-spacing:.18em;color:var(--pine)}.threat-block{padding-top:16px}.threat-pulse{font-size:8px;color:#b6654f;letter-spacing:.08em}.threat-pulse::first-letter{font-size:7px}.threat-block>p{margin:8px 0 11px}.threat-tip{background:#f3f1e9;padding:9px 10px;display:flex;gap:9px;align-items:flex-start;color:#79817c;font-size:9px;line-height:1.45}.tip-icon{font-size:13px;color:var(--red)}.controls-block{padding:16px 19px 12px}.control-row{display:flex;align-items:center;gap:4px;margin-top:10px}.keycap{height:20px;min-width:20px;padding:0 5px;border:1px solid #dedcd2;border-bottom-width:2px;border-radius:3px;text-align:center;line-height:18px;font:9px/18px var(--mono);color:#51605b;background:white}.keycap.wide{min-width:42px}.control-copy{margin-left:6px;font-size:9px;color:#838b85}.control-copy b{color:#5d6862;font-weight:600}.side-footer{margin-top:auto;border-top:1px solid var(--line);padding:12px 19px;color:#91958a;font-size:8px;letter-spacing:.04em}.side-footer span{color:var(--red);font-size:12px;margin-right:4px}.game-overlay{position:absolute;inset:0;background:#091517b8;display:flex;align-items:center;justify-content:center;z-index:3;transition:opacity .35s}.game-overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(360px,88%);padding:28px 32px 24px;background:#f8f6ed;text-align:center;border:1px solid #fff9;box-shadow:0 15px 50px #0005;position:relative}.overlay-snow{font-size:16px;letter-spacing:.6em;color:#b2c2b9;margin:0 0 15px}.overlay-card .eyebrow{margin-bottom:8px;font-size:8px}.overlay-card h2{font:700 clamp(27px,4vw,36px)/1.08 var(--serif);letter-spacing:-.03em;margin:0 0 11px;color:#1c302c}.overlay-card>p:not(.eyebrow){font-size:11px;line-height:1.65;color:#737b75;margin:0 auto 18px;max-width:285px}.primary-btn{border:0;background:var(--red);color:white;padding:13px 20px;min-width:190px;font:500 10px var(--mono);letter-spacing:.11em;cursor:pointer;transition:background .15s,transform .15s}.primary-btn:hover{background:#a73e36;transform:translateY(-1px)}.primary-btn span{font-size:14px;margin-left:8px}.overlay-hint{margin-top:16px;color:#a3a39a;font-size:7px;letter-spacing:.1em}.toast{position:absolute;z-index:2;left:50%;top:14px;transform:translate(-50%,-12px);background:#f6f1e4;color:#36453e;padding:9px 15px;font-size:10px;box-shadow:0 4px 16px #0003;opacity:0;pointer-events:none;transition:all .22s;white-space:nowrap;max-width:90%;text-align:center}.toast.show{opacity:1;transform:translate(-50%,0)}.keypad{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);width:min(330px,90%);padding:22px;background:#f8f6ed;text-align:center;box-shadow:0 15px 60px #0009;border:1px solid #fff}.keypad[hidden]{display:none}.keypad .eyebrow{font-size:8px;margin-bottom:8px}.keypad h3{font:600 19px var(--serif);margin:0 0 14px;color:#23372f}.code-display{font:500 26px var(--mono);letter-spacing:.25em;color:var(--pine);padding:10px;border:1px solid #dadfd5;background:#f0f2e9}.keypad-hint{color:#89918a;font-size:9px;line-height:1.5;margin:12px 0 15px}.small-btn{min-width:0;padding:11px 15px;font-size:9px}.touch-controls{display:none}.page-footer{display:flex;justify-content:space-between;padding:18px 2px;color:#9a9a8f;font-size:8px;letter-spacing:.12em}.page-footer span:last-child{color:#78817b}.mobile-break{display:none}
@media (min-width:1200px){.page-shell{padding-left:7%;padding-right:7%}.game-layout{grid-template-columns:minmax(0,1fr) 328px}}
@media(max-width:900px){.page-shell{padding:0 4%}.game-layout{grid-template-columns:minmax(0,1fr) 280px;gap:14px}.panel-block{padding-left:14px;padding-right:14px}.controls-block{padding-left:14px;padding-right:14px}.side-footer{padding-left:14px;padding-right:14px}.game-footline{padding:0 11px}.foot-note{font-size:9px}}
@media(max-width:700px){body{background-size:14px 14px}.page-shell{padding:0 15px}.topbar{height:56px}.brand{font-size:11px}.chapter-label{font-size:8px}.sound-toggle{font-size:12px}.sound-toggle span{display:none}.intro-row{padding:23px 0 18px;align-items:flex-end}.intro-row .eyebrow{font-size:8px;margin-bottom:8px}.intro-row h1{font-size:34px}.subtitle{font-size:10px;line-height:1.4;max-width:280px}.story-chip{min-width:0;width:135px;font-size:9px;line-height:1.5;padding-left:10px;gap:7px}.story-chip b{font-size:8px}.chip-icon{font-size:16px}.game-layout{display:flex;flex-direction:column;gap:12px}.game-topline{height:34px;padding:0 12px}.location{font-size:8px}.alert-status{font-size:8px}.game-footline{height:37px}.meter-track{width:70px}.meter-label,.meter-state{font-size:7px}.foot-note{font-size:8px}.side-panel{display:grid;grid-template-columns:1fr 1fr}.mission-block{grid-column:1/-1}.threat-block{border-bottom:0;border-right:1px solid var(--line)}.threat-block>p{font-size:10px}.threat-tip{font-size:8px;padding:7px}.controls-block{padding-top:16px}.control-row{gap:3px;margin-top:8px}.control-copy{font-size:8px;margin-left:3px}.keycap{min-width:17px;height:18px;line-height:16px;font-size:8px}.keycap.wide{min-width:35px}.side-footer{grid-column:1/-1;padding:9px 12px}.touch-controls{display:flex;justify-content:space-between;align-items:center;margin:2px 0 8px;padding:0 7px}.dpad{width:138px;height:115px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr);gap:4px}.dpad button,.touch-action{border:1px solid #d9d6cb;background:#fbfaf6;color:#43534c;box-shadow:0 2px 0 #d9d6cb;touch-action:none;user-select:none;-webkit-user-select:none}.dpad button{border-radius:8px;font-size:15px}.dpad button:nth-child(1){grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.dpad button:active,.touch-action:active{transform:translateY(2px);box-shadow:none;background:#eef0e8}.touch-action{width:60px;height:58px;border-radius:50%;font:600 17px var(--mono);color:var(--pine)}.touch-action small{display:block;font:7px var(--mono);letter-spacing:.08em;margin-top:1px}.sprint-touch{color:var(--red)}.page-footer{padding:12px 0;font-size:7px}.mobile-break{display:inline}}
@media(max-width:390px){.intro-row h1{font-size:30px}.story-chip{width:120px}.subtitle{max-width:210px}.chapter-label{letter-spacing:.02em}.page-shell{padding:0 10px}.panel-block{padding-left:10px;padding-right:10px}.objectives li{gap:7px}.objective-copy b{font-size:10px}.objective-copy small{font-size:8px}.side-footer{font-size:7px}.control-copy{font-size:7px}.controls-block{padding-left:9px;padding-right:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const TILE = 32, COLS = 22, ROWS = 16, W = TILE * COLS, H = TILE * ROWS;
  const map = Array.from({ length: ROWS }, (_, y) => Array.from({ length: COLS }, (_, x) =>
    x === 0 || y === 0 || x === COLS - 1 || y === ROWS - 1 ? '#' : '.'));
  const wall = (x, y) => { map[y][x] = '#'; };
  // Interior partitions make six connected rooms around the central passage.
  for (let x = 1; x <= 20; x++) wall(x, 7);
  for (const x of [4, 10, 17]) map[7][x] = '.';
  for (let y = 1; y <= 6; y++) { wall(7, y); wall(14, y); }
  for (const y of [4]) { map[y][7] = '.'; map[y][14] = '.'; }
  for (let y = 8; y <= 14; y++) { wall(7, y); wall(14, y); }
  for (const y of [11]) { map[y][7] = '.'; map[y][14] = '.'; }
  const exit = { x: 2, y: 1 };
  const itemSpots = { key: { x: 4, y: 3 }, cutters: { x: 18, y: 3 }, note: { x: 10, y: 12 } };
  const closetSpots = [{ x: 2, y: 10 }, { x: 11, y: 4 }, { x: 19, y: 10 }];
  const patrol = [{ x: 11, y: 5 }, { x: 13, y: 5 }, { x: 13, y: 11 }, { x: 18, y: 11 }, { x: 18, y: 3 }, { x: 16, y: 3 }, { x: 16, y: 11 }, { x: 10, y: 11 }, { x: 4, y: 11 }, { x: 4, y: 3 }, { x: 11, y: 5 }];
  const held = new Set();
  const ui = {
    overlay: document.getElementById('overlay'), title: document.getElementById('overlayTitle'),
    copy: document.getElementById('overlayCopy'), kicker: document.getElementById('overlayKicker'),
    start: document.getElementById('startBtn'), toast: document.getElementById('toast'),
    meter: document.getElementById('meterFill'), meterState: document.getElementById('meterState'),
    foot: document.getElementById('footMessage'), status: document.getElementById('statusText'),
    statusBox: document.querySelector('.alert-status'), step: document.getElementById('stepCount'),
    codeClue: document.getElementById('codeClue'), clueValue: document.getElementById('clueValue'),
    keypad: document.getElementById('keypad'), code: document.getElementById('codeDisplay'),
    objectives: document.getElementById('objectives'), sound: document.getElementById('soundBtn')
  };
  const state = {
    running: false, finished: false, caught: false, player: { x: 3, y: 12 }, guard: { x: 11, y: 5, dir: { x: 1, y: 0 } },
    items: { key: false, cutters: false, note: false }, code: '', hiding: false, suspicion: 0,
    lastMove: 0, lastGuard: 0, guardTarget: null, routeIndex: 0, routePath: [], chaseUntil: 0,
    noise: null, lastNoise: 0, facing: { x: 1, y: 0 }, keypadInput: '', toastTimer: 0,
    soundOn: true, audio: null, particles: [], startTime: 0, lastFrame: 0
  };
  let dpr = 1;
  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  new ResizeObserver(resize).observe(canvas);
  resize();

  function passable(x, y) { return x >= 0 && y >= 0 && x < COLS && y < ROWS && map[y][x] !== '#'; }
  function pointKey(p) { return `${p.x},${p.y}`; }
  function pathfind(start, goal) {
    if (!goal || (start.x === goal.x && start.y === goal.y)) return [];
    const queue = [start], came = new Map([[pointKey(start), null]]), dirs = [{ x: 1, y: 0 }, { x: -1, y: 0 }, { x: 0, y: 1 }, { x: 0, y: -1 }];
    let found = false;
    while (queue.length) {
      const p = queue.shift();
      if (p.x === goal.x && p.y === goal.y) { found = true; break; }
      for (const d of dirs) { const n = { x: p.x + d.x, y: p.y + d.y }, k = pointKey(n); if (passable(n.x, n.y) && !came.has(k)) { came.set(k, p); queue.push(n); } }
    }
    if (!found) return [];
    const result = []; let at = goal;
    while (at && !(at.x === start.x && at.y === start.y)) { result.unshift(at); at = came.get(pointKey(at)); }
    return result;
  }
  function tone(freq = 440, duration = .08, type = 'sine', volume = .035) {
    if (!state.soundOn) return;
    try {
      state.audio ||= new (window.AudioContext || window.webkitAudioContext)();
      if (state.audio.state === 'suspended') state.audio.resume();
      const o = state.audio.createOscillator(), g = state.audio.createGain(), now = state.audio.currentTime;
      o.type = type; o.frequency.setValueAtTime(freq, now); g.gain.setValueAtTime(volume, now); g.gain.exponentialRampToValueAtTime(.001, now + duration);
      o.connect(g); g.connect(state.audio.destination); o.start(now); o.stop(now + duration);
    } catch (_) { /* Audio is an optional flourish. */ }
  }
  function showToast(message, duration = 1900) {
    ui.toast.textContent = message; ui.toast.classList.add('show'); clearTimeout(state.toastTimer);
    state.toastTimer = setTimeout(() => ui.toast.classList.remove('show'), duration);
  }
  function setObjective(name) { const row = ui.objectives.querySelector(`[data-objective="${name}"]`); if (row) row.classList.add('done'); }
  function objectiveCount() { return Object.values(state.items).filter(Boolean).length; }
  function updateHUD() {
    ui.step.textContent = `${objectiveCount()} / 3`;
    ui.meter.style.width = `${Math.max(0, Math.min(100, state.suspicion))}%`;
    const danger = state.suspicion > 8;
    ui.meterState.textContent = danger ? 'SEEN' : 'CLEAR'; ui.meterState.classList.toggle('danger', danger);
    ui.status.textContent = state.hiding ? 'HIDDEN' : danger ? 'ALERT' : state.guardTarget ? 'SEARCHING' : 'QUIET';
    ui.statusBox.classList.toggle('alerted', danger || !!state.guardTarget);
    ui.foot.textContent = state.hiding ? 'Hold still. Let him pass.' : danger ? 'He can see you—break line of sight!' : state.guardTarget ? 'He heard something. Stay out of sight.' : 'Stay out of the light.';
  }
  function collect() {
    for (const [name, pos] of Object.entries(itemSpots)) {
      if (!state.items[name] && state.player.x === pos.x && state.player.y === pos.y) {
        state.items[name] = true; setObjective(name); tone(name === 'note' ? 660 : 520, .15, 'triangle', .05);
        if (name === 'key') showToast('FOUND: The cabin key. One lock down.');
        if (name === 'cutters') showToast('FOUND: Bolt cutters. The chain won’t hold you.');
        if (name === 'note') { state.code = '2412'; ui.codeClue.hidden = false; ui.clueValue.textContent = '2 4 1 2'; showToast('FOUND: A note with the shed code — 2412.'); }
      }
    }
  }
  function movePlayer(dx, dy, now, sprint) {
    if (!state.running || state.hiding || ui.keypad.hidden === false) return;
    const nx = state.player.x + dx, ny = state.player.y + dy;
    if (!passable(nx, ny)) { tone(100, .035, 'sine', .009); return; }
    state.player.x = nx; state.player.y = ny; state.facing = { x: dx, y: dy };
    state.lastMove = now; collect();
    if (sprint) { state.noise = { x: nx, y: ny }; state.lastNoise = now; tone(115, .035, 'triangle', .008); }
    else tone(170, .025, 'sine', .006);
    if (state.guardTarget && state.suspicion < 12) state.chaseUntil = now + 1900;
  }
  function moveGuard(now) {
    let target;
    if (state.guardTarget && now < state.chaseUntil) target = state.guardTarget;
    else if (state.noise && now - state.lastNoise < 1050 && Math.abs(state.guard.x - state.noise.x) + Math.abs(state.guard.y - state.noise.y) < 8) target = state.noise;
    else {
      state.guardTarget = null; state.noise = null;
      const waypoint = patrol[state.routeIndex % patrol.length];
      if (state.guard.x === waypoint.x && state.guard.y === waypoint.y) state.routeIndex++;
      target = patrol[state.routeIndex % patrol.length];
    }
    let route = pathfind(state.guard, target);
    if (!route.length && target && !(target.x === state.guard.x && target.y === state.guard.y)) route = pathfind(state.guard, patrol[state.routeIndex % patrol.length]);
    if (route.length) {
      const next = route[0]; state.guard.dir = { x: next.x - state.guard.x, y: next.y - state.guard.y }; state.guard.x = next.x; state.guard.y = next.y;
    }
  }
  function seesPlayer() {
    if (state.hiding) return false;
    const dx = state.player.x - state.guard.x, dy = state.player.y - state.guard.y, dist = Math.hypot(dx, dy);
    if (dist > 6.1) return false;
    const dot = dist < 1.6 ? 1 : (dx * state.guard.dir.x + dy * state.guard.dir.y) / dist;
    if (dot < .42) return false;
    const steps = Math.ceil(dist * 5);
    for (let i = 1; i < steps; i++) { const x = Math.floor(state.guard.x + dx * i / steps), y = Math.floor(state.guard.y + dy * i / steps); if (!passable(x, y)) return false; }
    return true;
  }
  function interact() {
    if (!state.running || ui.keypad.hidden === false) return;
    if (state.hiding) { state.hiding = false; showToast('You slip out of the closet.'); tone(330, .07); updateHUD(); return; }
    const closet = closetSpots.find(p => Math.abs(p.x - state.player.x) + Math.abs(p.y - state.player.y) <= 1);
    if (closet) { state.hiding = true; state.guardTarget = null; state.suspicion = Math.max(0, state.suspicion - 15); showToast('Hidden. Wait for the footsteps to fade.'); tone(480, .1, 'triangle'); updateHUD(); return; }
