import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ channel: 'chromium', headless: false });
const failures = [];
async function instrument(page) {
  page.on('pageerror', error => failures.push(error.message));
  await page.route('**/game.js', async route => {
    const response = await route.fetch();
    const source = await response.text();
    const marker = '  ui.start.addEventListener(\'click\', startGame);';
    const addition = '  window.__silentTest = { state, ui, interact, catchPlayer, startGame };\n' + marker;
    if (!source.includes(marker)) throw new Error('Instrumentation anchor not found');
    await route.fulfill({ response, body: source.replace(marker, addition) });
  });
}
try {
  const desktop = await browser.newPage({ viewport: { width: 1100, height: 900 } });
  await instrument(desktop);
  await desktop.goto('http://localhost:3002');
  await desktop.locator('#startBtn').click();
  await desktop.waitForFunction(() => window.__silentTest?.state.running);
  await desktop.evaluate(() => {
    const { state, interact } = window.__silentTest;
    state.items = { key: true, cutters: true, note: true };
    state.code = '2412';
    state.player = { x: 2, y: 2 };
    interact();
  });
  if (!await desktop.locator('#keypad').isVisible()) throw new Error('Keypad did not open');
  for (const digit of ['2', '4', '1', '2']) await desktop.locator(`[data-digit="${digit}"]`).click();
  if ((await desktop.locator('#codeDisplay').textContent()).trim() !== '2 4 1 2') throw new Error('Digit buttons did not populate code');
  await desktop.screenshot({ path: '/tmp/opencode/silent-night-captures/keypad-desktop.jpg', type: 'jpeg', quality: 78 });
  await desktop.locator('#codeConfirm').click();
  await desktop.waitForFunction(() => window.__silentTest.state.finished);
  if (!await desktop.locator('#overlay').isVisible() || !(await desktop.locator('#overlayTitle').textContent()).includes('Home for')) throw new Error('Correct code did not win');
  await desktop.locator('#startBtn').click();
  await desktop.evaluate(() => window.__silentTest.catchPlayer());
  if (!(await desktop.locator('#overlayTitle').textContent()).includes('Not this')) throw new Error('Caught state did not show retry overlay');
  await desktop.locator('#startBtn').click();
  await desktop.waitForFunction(() => window.__silentTest.state.running && !window.__silentTest.state.finished);
  if (await desktop.evaluate(() => Object.values(window.__silentTest.state.items).some(Boolean))) throw new Error('Retry did not reset objectives');
  console.log('Desktop: keypad digit entry, unlock/win, caught overlay, and retry/reset passed.');
  await desktop.close();

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  await instrument(mobile);
  await mobile.goto('http://localhost:3002');
  await mobile.locator('#startBtn').tap();
  await mobile.waitForFunction(() => window.__silentTest?.state.running);
  if (await mobile.locator('.touch-controls').evaluate(el => getComputedStyle(el).display) === 'none') throw new Error('Mobile touch controls are hidden');
  await mobile.evaluate(() => { window.__silentTest.state.player = { x: 2, y: 10 }; });
  await mobile.locator('#interactBtn').tap();
  if (!await mobile.evaluate(() => window.__silentTest.state.hiding)) throw new Error('Touch interact did not hide player');
  await mobile.locator('#interactBtn').tap();
  if (await mobile.evaluate(() => window.__silentTest.state.hiding)) throw new Error('Touch interact did not unhide player');
  await mobile.evaluate(() => { window.__silentTest.state.items = { key: true, cutters: true, note: true }; window.__silentTest.state.code = '2412'; window.__silentTest.state.player = { x: 2, y: 2 }; window.__silentTest.interact(); });
  for (const digit of ['2', '4', '1', '2']) await mobile.locator(`[data-digit="${digit}"]`).tap();
  await mobile.screenshot({ path: '/tmp/opencode/silent-night-captures/keypad-mobile.jpg', type: 'jpeg', quality: 78 });
  await mobile.locator('#codeConfirm').tap();
  await mobile.waitForFunction(() => window.__silentTest.state.finished);
  console.log('Mobile: touch controls visible, hide/unhide tap interaction, keypad entry, and escape passed.');
  if (failures.length) throw new Error(`Browser errors: ${failures.join('; ')}`);
} finally { await browser.close(); }

